// The host-owned label for a set written by the user's own model (ADR-028 section 8). The text is
// built here from the stored model name and is always rendered as plain text; the activity itself
// can't change it, hide it or dismiss it.

import type { ReactNode } from "react";
import { aiLabel, aiTag } from "../companion/generate";
import "../styles/generated.css";
import type { ActivityInfo } from "./ActivityHost";

/**
 * "AI-generated by <model>. It can be wrong." (body sets add "Stop if anything feels
 * uncomfortable."). In the page, not a tooltip, and never dismissible. Nothing for other
 * activities.
 */
export function AiNotice({ info, extra }: { info: ActivityInfo; extra?: ReactNode }) {
  const label = aiLabel(info);
  if (!label) return null;
  return (
    <div className="ai-notice" data-testid="ai-notice">
      <p className="ai-notice-text">{label}</p>
      {extra}
    </div>
  );
}

/** The small tag on cards, in the paused view and in Settings: "AI-generated · <model>". */
export function AiTag({ info }: { info: ActivityInfo }) {
  const tag = aiTag(info);
  if (!tag) return null;
  return (
    <span className="ai-tag" data-testid="ai-tag">
      {tag}
    </span>
  );
}
